# Generated by Claude Agentic SDLC Workflow
import functools
import re
import sqlite3

from flask import Blueprint, current_app, flash, g, redirect, render_template, request, session, url_for
from werkzeug.security import check_password_hash, generate_password_hash

from . import security
from .db import get_db, utcnow_iso

bp = Blueprint("auth", __name__, url_prefix="/auth")

USERNAME_RE = re.compile(r"^[A-Za-z0-9_.-]{3,30}$")
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
MAX_EMAIL_LENGTH = 254

# Verified for unknown users so login timing does not reveal whether an account exists.
_DUMMY_HASH = generate_password_hash("not-a-real-password")


def login_required(view):
    @functools.wraps(view)
    def wrapped(*args, **kwargs):
        if g.get("user") is None:
            return redirect(url_for("auth.login"))
        return view(*args, **kwargs)

    return wrapped


@bp.route("/register", methods=("GET", "POST"))
def register():
    if g.user is not None:
        return redirect(url_for("blog.index"))

    if request.method == "GET":
        return render_template("auth/register.html", username="", email="", errors=[])

    username = request.form.get("username", "").strip()
    email = request.form.get("email", "").strip().lower()
    password = request.form.get("password", "")
    errors = _validate_registration(username, email, password)

    db = get_db()
    if not errors:
        if db.execute("SELECT 1 FROM user WHERE username = ?", (username,)).fetchone():
            errors.append("That username is already taken.")
        if db.execute("SELECT 1 FROM user WHERE email = ?", (email,)).fetchone():
            errors.append("That email is already registered.")

    if not errors:
        try:
            db.execute(
                "INSERT INTO user (username, email, password_hash, created_at) VALUES (?, ?, ?, ?)",
                (username, email, generate_password_hash(password), utcnow_iso()),
            )
            db.commit()
        except sqlite3.IntegrityError:
            errors.append("That username or email is already registered.")

    if errors:
        return render_template("auth/register.html", username=username, email=email, errors=errors), 400

    flash("Account created. Please log in.")
    return redirect(url_for("auth.login"))


def _validate_registration(username, email, password):
    errors = []
    if not username:
        errors.append("Username is required.")
    elif not USERNAME_RE.match(username):
        errors.append("Username must be 3-30 characters: letters, numbers, underscore, dot or hyphen.")

    if not email:
        errors.append("Email is required.")
    elif len(email) > MAX_EMAIL_LENGTH or not EMAIL_RE.match(email):
        errors.append("Enter a valid email address.")

    min_len = current_app.config["MIN_PASSWORD_LENGTH"]
    max_len = current_app.config["MAX_PASSWORD_LENGTH"]
    if not password:
        errors.append("Password is required.")
    elif len(password) < min_len:
        errors.append(f"Password must be at least {min_len} characters.")
    elif len(password) > max_len:
        errors.append(f"Password must be at most {max_len} characters.")
    return errors


@bp.route("/login", methods=("GET", "POST"))
def login():
    if g.user is not None:
        return redirect(url_for("blog.index"))

    if request.method == "GET":
        return render_template("auth/login.html", identifier="", error=None)

    identifier = request.form.get("identifier", "").strip()
    password = request.form.get("password", "")
    user = _find_user(identifier)

    valid = False
    if len(password) <= current_app.config["MAX_PASSWORD_LENGTH"]:
        if user is None:
            check_password_hash(_DUMMY_HASH, password)
        else:
            valid = check_password_hash(user["password_hash"], password)

    if not valid:
        error = "Invalid username/email or password."
        return render_template("auth/login.html", identifier=identifier, error=error), 401

    session.clear()
    session["user_id"] = user["id"]
    session["last_active"] = security.now()
    return redirect(url_for("blog.index"))


def _find_user(identifier):
    if not identifier:
        return None
    db = get_db()
    if "@" in identifier:
        return db.execute("SELECT * FROM user WHERE email = ?", (identifier.lower(),)).fetchone()
    return db.execute("SELECT * FROM user WHERE username = ?", (identifier,)).fetchone()


@bp.route("/logout", methods=("POST",))
def logout():
    session.clear()
    flash("You have been logged out.")
    return redirect(url_for("auth.login"))


@bp.route("/keepalive", methods=("POST",))
def keepalive():
    if g.user is None:
        return "", 401
    return "", 204
